 if(!placement.bound_to(x.common))fail("BornPlacementSameCandidateRequired");NativeBornCharacterSourceRead originals(x);auto actual=take(originals.read_original_birth(ref));auto origin=take(read_born_character_origin_v2(x.common,foundation,catalog,originals,actual.birth->actor_id,take(x.access.people->read_current_moment())));(void)origin;
 if(!actual.birth->location_result_ref)fail("BornActualLocationResultRequired",ref.birth_fact_id);MomentOwnerSource source{{"family_birth","family_birth_recorded",ref.birth_fact_id},4};auto applied=take(placement.read_birth_placement_application(source,*actual.birth->location_result_ref));
 const auto& terms=actual.accepted->confirmation->terms;
 if(!applied.actual_placement||applied.delivery_actor_id!=terms.gestating_actor_id||applied.birth_arrangement_id!=actual.birth->accepted_id||applied.child_actor_id!=actual.birth->actor_id||!same(applied.occurred_at,actual.occurred_at)||!same(applied.actual_birth_source,source)||!same(applied.location_result,*actual.birth->location_result_ref))fail("BornActualPlacementBindingMismatch",ref.birth_fact_id);
